INSERT INTO public.movies (title, description, poster_url, duration_minutes, genres, languages, certificate, rating, release_date, status, tmdb_id)
VALUES
  ('Inception', 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.', 'https://image.tmdb.org/t/p/w500/qmDpIHrmpJINaRKAfWQfftjCdyi.jpg', 148, ARRAY['Action','Thriller','Science Fiction','Mystery','Adventure'], ARRAY['English'], 'UA', 8.1, '2010-07-14', 'now_showing'::public.movie_status, 27205),
  ('The Dark Knight', 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.', 'https://image.tmdb.org/t/p/w500/1hRoyzDtpgMU7Dz4JF22RANzQO7.jpg', 152, ARRAY['Drama','Action','Crime','Thriller'], ARRAY['English','普通话'], 'UA', 8.3, '2008-07-16', 'now_showing'::public.movie_status, 155),
  ('Avatar', 'In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.', 'https://image.tmdb.org/t/p/w500/kmcqlZGaSh20zpTbuoF0Cdn07dT.jpg', 162, ARRAY['Action','Adventure','Fantasy','Science Fiction'], ARRAY['English','Español'], 'UA', 7.2, '2009-12-10', 'now_showing'::public.movie_status, 19995),
  ('The Avengers', 'When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!', 'https://image.tmdb.org/t/p/w500/cezWGskPY5x7GaglTTRN4Fugfb8.jpg', 143, ARRAY['Science Fiction','Action','Adventure'], ARRAY['English'], 'UA', 7.4, '2012-04-25', 'now_showing'::public.movie_status, 24428),
  ('Deadpool', 'Deadpool tells the origin story of former Special Forces operative turned mercenary Wade Wilson, who after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.', 'https://image.tmdb.org/t/p/w500/inVq3FRqcYIRl2la8iZikYYxFNR.jpg', 108, ARRAY['Action','Adventure','Comedy'], ARRAY['English'], 'UA', 7.4, '2016-02-09', 'now_showing'::public.movie_status, 293660),
  ('Interstellar', 'Interstellar chronicles the adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.', 'https://image.tmdb.org/t/p/w500/nBNZadXqJSdt05SHLqgT0HuC5Gm.jpg', 169, ARRAY['Adventure','Drama','Science Fiction'], ARRAY['English'], 'UA', 8.1, '2014-11-05', 'now_showing'::public.movie_status, 157336),
  ('Django Unchained', 'With the help of a German bounty hunter, a freed slave sets out to rescue his wife from a brutal Mississippi plantation owner.', 'https://image.tmdb.org/t/p/w500/5WJnxuw41sddupf8cwOxYftuvJG.jpg', 165, ARRAY['Drama','Western'], ARRAY['English','Français'], 'UA', 7.8, '2012-12-25', 'now_showing'::public.movie_status, 68718),
  ('Guardians of the Galaxy', 'Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.', 'https://image.tmdb.org/t/p/w500/y31QB9kn3XSudA15tV7UWQ9XLuW.jpg', 121, ARRAY['Action','Science Fiction','Adventure'], ARRAY['English'], 'UA', 7.9, '2014-07-30', 'now_showing'::public.movie_status, 118340),
  ('Fight Club', 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.', 'https://image.tmdb.org/t/p/w500/adw6Lq9FiC9zjYEpOqfq03ituwp.jpg', 139, ARRAY['Drama'], ARRAY['English'], 'UA', 8.3, '1999-10-15', 'now_showing'::public.movie_status, 550),
  ('The Hunger Games', 'Every year in the ruins of what was once North America, the nation of Panem forces each of its twelve districts to send a teenage boy and girl to compete in the Hunger Games.  Part twisted entertainment, part government intimidation tactic, the Hunger Games are a nationally televised event in which “Tributes” must fight with one another until one survivor remains.  Pitted against highly-trained Tributes who have prepared for these Games their entire lives, Katniss is forced to rely upon her sharp instincts as well as the mentorship of drunken former victor Haymitch Abernathy.  If she’s ever to return home to District 12, Katniss must make impossible choices in the arena that weigh survival against humanity and life against love. The world will be watching.', 'https://image.tmdb.org/t/p/w500/iLJdwmzrHFjFwI5lvYAT1gcpRuA.jpg', 142, ARRAY['Science Fiction','Adventure','Fantasy'], ARRAY['English'], 'UA', 6.9, '2012-03-12', 'now_showing'::public.movie_status, 70160),
  ('Mad Max: Fury Road', 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order. There''s Max, a man of action and a man of few words, who seeks peace of mind following the loss of his wife and child in the aftermath of the chaos. And Furiosa, a woman of action and a woman who believes her path to survival may be achieved if she can make it across the desert back to her childhood homeland.', 'https://image.tmdb.org/t/p/w500/kqjL17yufvn9OVLyXYpvtyrFfak.jpg', 120, ARRAY['Action','Adventure','Science Fiction','Thriller'], ARRAY['English'], 'UA', 7.3, '2015-05-13', 'now_showing'::public.movie_status, 76341),
  ('The Dark Knight Rises', 'Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.', 'https://image.tmdb.org/t/p/w500/dEYnvnUfXrqvqeRSqvIEtmzhoA8.jpg', 165, ARRAY['Action','Crime','Drama','Thriller'], ARRAY['English'], 'UA', 7.6, '2012-07-16', 'now_showing'::public.movie_status, 49026),
  ('The Matrix', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.', 'https://image.tmdb.org/t/p/w500/hEpWvX6Bp79eLxY1kX5ZZJcme5U.jpg', 136, ARRAY['Action','Science Fiction'], ARRAY['English'], 'UA', 7.9, '1999-03-30', 'now_showing'::public.movie_status, 603),
  ('Iron Man', 'After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.', 'https://image.tmdb.org/t/p/w500/848chlIWVT41VtAAgyh9bWymAYb.jpg', 126, ARRAY['Action','Science Fiction','Adventure'], ARRAY['English','فارسی'], 'UA', 7.4, '2008-04-30', 'now_showing'::public.movie_status, 1726),
  ('Iron Man 3', 'When Tony Stark''s world is torn apart by a formidable terrorist called the Mandarin, he starts an odyssey of rebuilding and retribution.', 'https://image.tmdb.org/t/p/w500/1Ilv6ryHUv6rt9zIsbSEJUmmbEi.jpg', 130, ARRAY['Action','Adventure','Science Fiction'], ARRAY['English'], 'UA', 6.8, '2013-04-18', 'now_showing'::public.movie_status, 68721),
  ('The Lord of the Rings: The Fellowship of the Ring', 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', 'https://image.tmdb.org/t/p/w500/bxVxZb5O9OxCO0oRUNdCnpy9NST.jpg', 178, ARRAY['Adventure','Fantasy','Action'], ARRAY['English'], 'UA', 8.0, '2001-12-18', 'now_showing'::public.movie_status, 120),
  ('Jurassic World', 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.', 'https://image.tmdb.org/t/p/w500/jjBgi2r5cRt36xF6iNUEhzscEcb.jpg', 124, ARRAY['Action','Adventure','Science Fiction','Thriller'], ARRAY['English'], 'UA', 6.5, '2015-06-09', 'now_showing'::public.movie_status, 135397),
  ('Pulp Fiction', 'A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.', 'https://image.tmdb.org/t/p/w500/dM2w364MScsjFf8pfMbaWUcWrR.jpg', 154, ARRAY['Thriller','Crime'], ARRAY['English','Español'], 'UA', 8.3, '1994-09-10', 'now_showing'::public.movie_status, 680),
  ('The Hobbit: An Unexpected Journey', 'Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.', 'https://image.tmdb.org/t/p/w500/ysX7vDmSh5O19vFjAi56WL7l4nk.jpg', 169, ARRAY['Adventure','Fantasy','Action'], ARRAY['English'], 'UA', 7.0, '2012-11-26', 'now_showing'::public.movie_status, 49051),
  ('The Shawshank Redemption', 'Framed in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.', 'https://image.tmdb.org/t/p/w500/9O7gLzmreU0nGkIB6K3BsJbzvNv.jpg', 142, ARRAY['Drama','Crime'], ARRAY['English'], 'UA', 8.5, '1994-09-23', 'now_showing'::public.movie_status, 278),
  ('Forrest Gump', 'A man with a low IQ has accomplished great things in his life and been present during significant historic events - in each case, far exceeding what anyone imagined he could do. Yet, despite all the things he has attained, his one true love eludes him. ''Forrest Gump'' is the story of a man who rose above his challenges, and who proved that determination, courage, and love are more important than ability.', 'https://image.tmdb.org/t/p/w500/yE5d3BUhE8hCnkMUJOo1QDoOGNz.jpg', 142, ARRAY['Comedy','Drama','Romance'], ARRAY['English'], 'UA', 8.2, '1994-07-06', 'now_showing'::public.movie_status, 13),
  ('Star Wars: The Force Awakens', 'Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.', 'https://image.tmdb.org/t/p/w500/weUSwMdQIa3NaXVzwUoIIcAi85d.jpg', 136, ARRAY['Action','Adventure','Science Fiction','Fantasy'], ARRAY['English'], 'UA', 7.5, '2015-12-15', 'now_showing'::public.movie_status, 140607),
  ('Titanic', '84 years later, a 101-year-old woman named Rose DeWitt Bukater tells the story to her granddaughter Lizzy Calvert, Brock Lovett, Lewis Bodine, Bobby Buell and Anatoly Mikailavich on the Keldysh about her life set in April 10th 1912, on a ship called Titanic when young Rose boards the departing ship with the upper-class passengers and her mother, Ruth DeWitt Bukater, and her fiancé, Caledon Hockley. Meanwhile, a drifter and artist named Jack Dawson and his best friend Fabrizio De Rossi win third-class tickets to the ship in a game. And she explains the whole story from departure until the death of Titanic on its first and last voyage April 15th, 1912 at 2:20 in the morning.', 'https://image.tmdb.org/t/p/w500/kHXEpyfl6zqn8a6YuozZUujufXf.jpg', 194, ARRAY['Drama','Romance','Thriller'], ARRAY['English','Français'], 'UA', 7.5, '1997-11-18', 'now_showing'::public.movie_status, 597),
  ('Skyfall', 'When Bond''s latest assignment goes gravely wrong and agents around the world are exposed, MI6 is attacked forcing M to relocate the agency. These events cause her authority and position to be challenged by Gareth Mallory, the new Chairman of the Intelligence and Security Committee. With MI6 now compromised from both inside and out, M is left with one ally she can trust: Bond. 007 takes to the shadows - aided only by field agent, Eve - following a trail to the mysterious Silva, whose lethal and hidden motives have yet to reveal themselves.', 'https://image.tmdb.org/t/p/w500/9qUcmHiPpfTJTacyZyxfGTnSz0V.jpg', 143, ARRAY['Action','Adventure','Thriller'], ARRAY['English'], 'UA', 6.9, '2012-10-25', 'now_showing'::public.movie_status, 37724),
  ('Suicide Squad', 'From DC Comics comes the Suicide Squad, an antihero team of incarcerated supervillains who act as deniable assets for the United States government, undertaking high-risk black ops missions in exchange for commuted prison sentences.', 'https://image.tmdb.org/t/p/w500/e1mjopzAS2KNsvpbpahQ1a6SkSn.jpg', 123, ARRAY['Action','Adventure','Crime','Fantasy','Science Fiction'], ARRAY['English'], 'UA', 5.9, '2016-08-02', 'now_showing'::public.movie_status, 297761),
  ('The Lord of the Rings: The Two Towers', 'Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin. All along, nefarious wizard Saruman awaits the Fellowship members at the Orthanc Tower in Isengard.', 'https://image.tmdb.org/t/p/w500/wf3v0Pn09jnT5HSaYal7Ami3bdA.jpg', 179, ARRAY['Adventure','Fantasy','Action'], ARRAY['English'], 'UA', 8.0, '2002-12-18', 'now_showing'::public.movie_status, 121),
  ('Batman Begins', 'Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City.  Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.', 'https://image.tmdb.org/t/p/w500/dr6x4GyyegBWtinPBzipY02J2lV.jpg', 140, ARRAY['Action','Crime','Drama'], ARRAY['English','اردو'], 'UA', 7.5, '2005-06-10', 'now_showing'::public.movie_status, 272),
  ('Captain America: Civil War', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.', 'https://image.tmdb.org/t/p/w500/kSBXou5Ac7vEqKd97wotJumyJvU.jpg', 147, ARRAY['Adventure','Action','Science Fiction'], ARRAY['Română','English'], 'UA', 7.1, '2016-04-27', 'now_showing'::public.movie_status, 271110),
  ('The Martian', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.', 'https://image.tmdb.org/t/p/w500/5aGhaIHYuQbqlHWvWYqMCnj40y2.jpg', 141, ARRAY['Drama','Adventure','Science Fiction'], ARRAY['English','普通话'], 'UA', 7.6, '2015-09-30', 'now_showing'::public.movie_status, 286217),
  ('Pirates of the Caribbean: The Curse of the Black Pearl', 'Jack Sparrow, a freewheeling 17th-century pirate who roams the Caribbean Sea, butts heads with a rival pirate bent on pillaging the village of Port Royal. When the governor''s daughter is kidnapped, Sparrow decides to help the girl''s love save her. But their seafaring mission is hardly simple.', 'https://image.tmdb.org/t/p/w500/tkt9xR1kNX5R9rCebASKck44si2.jpg', 143, ARRAY['Adventure','Fantasy','Action'], ARRAY['English'], 'UA', 7.5, '2003-07-09', 'now_showing'::public.movie_status, 22),
  ('Batman v Superman: Dawn of Justice', 'Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.', 'https://image.tmdb.org/t/p/w500/cGOPbv9wA5gEejkUN892JrveARt.jpg', 151, ARRAY['Action','Adventure','Fantasy'], ARRAY['English'], 'UA', 5.7, '2016-03-23', 'now_showing'::public.movie_status, 209112),
  ('Harry Potter and the Philosopher''s Stone', 'Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard -- with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths -- and about the villain who''s to blame.', 'https://image.tmdb.org/t/p/w500/dCtFvscYcXQKTNvyyaQr2g2UacJ.jpg', 152, ARRAY['Adventure','Fantasy','Family'], ARRAY['English'], 'UA', 7.5, '2001-11-16', 'now_showing'::public.movie_status, 671),
  ('Captain America: The First Avenger', 'Predominantly set during World War II, Steve Rogers is a sickly man from Brooklyn who''s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler''s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.', 'https://image.tmdb.org/t/p/w500/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg', 124, ARRAY['Action','Adventure','Science Fiction'], ARRAY['Français','Norsk'], 'UA', 6.6, '2011-07-22', 'now_showing'::public.movie_status, 1771),
  ('Up', 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.', 'https://image.tmdb.org/t/p/w500/nk11pvocdb5zbFhX5oq5YiLPYMo.jpg', 96, ARRAY['Animation','Comedy','Family','Adventure'], ARRAY['English'], 'UA', 7.8, '2009-05-13', 'now_showing'::public.movie_status, 14160),
  ('Iron Man 2', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James ''Rhodey'' Rhodes at his side, must forge new alliances – and confront powerful enemies.', 'https://image.tmdb.org/t/p/w500/ArqpkNYGfcTIA6umWt6xihfIZZv.jpg', 124, ARRAY['Adventure','Action','Science Fiction'], ARRAY['English','Pусский'], 'UA', 6.6, '2010-04-28', 'now_showing'::public.movie_status, 10138),
  ('Avengers: Age of Ultron', 'When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.', 'https://image.tmdb.org/t/p/w500/t90Y3G8UGQp0f0DrP60wRu9gfrH.jpg', 141, ARRAY['Action','Adventure','Science Fiction'], ARRAY['English'], 'UA', 7.3, '2015-04-22', 'now_showing'::public.movie_status, 99861),
  ('Star Wars', 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.', 'https://image.tmdb.org/t/p/w500/btTdmkgIvOi0FFip1sPuZI2oQG6.jpg', 121, ARRAY['Adventure','Action','Science Fiction'], ARRAY['English'], 'UA', 8.1, '1977-05-25', 'now_showing'::public.movie_status, 11),
  ('The Wolf of Wall Street', 'A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.', 'https://image.tmdb.org/t/p/w500/vK1o5rZGqxyovfIhZyMELhk03wO.jpg', 180, ARRAY['Crime','Drama','Comedy'], ARRAY['Français','English'], 'UA', 7.9, '2013-12-25', 'now_showing'::public.movie_status, 106646),
  ('Inside Out', 'Growing up can be a bumpy road, and it''s no exception for Riley, who is uprooted from her Midwest life when her father starts a new job in San Francisco. Like all of us, Riley is guided by her emotions - Joy, Fear, Anger, Disgust and Sadness. The emotions live in Headquarters, the control center inside Riley''s mind, where they help advise her through everyday life. As Riley and her emotions struggle to adjust to a new life in San Francisco, turmoil ensues in Headquarters. Although Joy, Riley''s main and most important emotion, tries to keep things positive, the emotions conflict on how best to navigate a new city, house and school.', 'https://image.tmdb.org/t/p/w500/aAmfIX3TT40zUHGcCKrlOZRKC7u.jpg', 94, ARRAY['Drama','Comedy','Animation','Family'], ARRAY['English'], 'UA', 7.9, '2015-06-09', 'now_showing'::public.movie_status, 150540),
  ('The Amazing Spider-Man', 'Peter Parker is an outcast high schooler abandoned by his parents as a boy, leaving him to be raised by his Uncle Ben and Aunt May. Like most teenagers, Peter is trying to figure out who he is and how he got to be the person he is today. As Peter discovers a mysterious briefcase that belonged to his father, he begins a quest to understand his parents'' disappearance – leading him directly to Oscorp and the lab of Dr. Curt Connors, his father''s former partner. As Spider-Man is set on a collision course with Connors'' alter ego, The Lizard, Peter will make life-altering choices to use his powers and shape his destiny to become a hero.', 'https://image.tmdb.org/t/p/w500/eA2D86Y6VPWuUzZyatiLBwpTilQ.jpg', 136, ARRAY['Action','Adventure','Fantasy'], ARRAY['English'], 'UA', 6.5, '2012-06-27', 'now_showing'::public.movie_status, 1930),
  ('Thor', 'Against his father Odin''s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.', 'https://image.tmdb.org/t/p/w500/bIuOWTtyFPjsFDevqvF3QrD1aun.jpg', 115, ARRAY['Adventure','Fantasy','Action'], ARRAY['English'], 'UA', 6.6, '2011-04-21', 'now_showing'::public.movie_status, 10195),
  ('The Hunger Games: Catching Fire', 'Katniss Everdeen has returned home safe after winning the 74th Annual Hunger Games along with fellow tribute Peeta Mellark. Winning means that they must turn around and leave their family and close friends, embarking on a "Victor''s Tour" of the districts. Along the way Katniss senses that a rebellion is simmering, but the Capitol is still very much in control as President Snow prepares the 75th Annual Hunger Games (The Quarter Quell) - a competition that could change Panem forever.', 'https://image.tmdb.org/t/p/w500/Hn0KgefVEp0GkdTexS6gfKTMfi.jpg', 146, ARRAY['Adventure','Action','Science Fiction'], ARRAY['English'], 'UA', 7.4, '2013-11-15', 'now_showing'::public.movie_status, 101299),
  ('Inglourious Basterds', 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as "The Basterds" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.', 'https://image.tmdb.org/t/p/w500/ai0LXkzVM3hMjDhvFdKMUemoBe.jpg', 153, ARRAY['Drama','Action','Thriller','War'], ARRAY['Deutsch','English'], 'UA', 7.9, '2009-08-18', 'now_showing'::public.movie_status, 16869),
  ('Despicable Me', 'Villainous Gru lives up to his reputation as a despicable, deplorable and downright unlikable guy when he hatches a plan to steal the moon from the sky. But he has a tough time staying on task after three orphans land in his care.', 'https://image.tmdb.org/t/p/w500/4zHJhBSY4kNZXfhTlmy2TzXD51M.jpg', 95, ARRAY['Animation','Family'], ARRAY['English'], 'UA', 7.1, '2010-07-08', 'now_showing'::public.movie_status, 20352),
  ('Shutter Island', 'World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by his troubling visions and also by a mysterious doctor.', 'https://image.tmdb.org/t/p/w500/aZqKsvpJDFy2UzUMsdskNFbfkOd.jpg', 138, ARRAY['Drama','Thriller','Mystery'], ARRAY['English','Deutsch'], 'UA', 7.8, '2010-02-18', 'now_showing'::public.movie_status, 11324),
  ('The Revenant', 'In the 1820s, a frontiersman, Hugh Glass, sets out on a path of vengeance against those who left him for dead after a bear mauling.', 'https://image.tmdb.org/t/p/w500/oXUWEc5i3wYyFnL1Ycu8ppxxPvs.jpg', 156, ARRAY['Western','Drama','Adventure','Thriller'], ARRAY['English','Français'], 'UA', 7.3, '2015-12-25', 'now_showing'::public.movie_status, 281957),
  ('Man of Steel', 'A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.', 'https://image.tmdb.org/t/p/w500/xWlaTLnD8NJMTT9PGOD9z5re1SL.jpg', 143, ARRAY['Action','Adventure','Fantasy','Science Fiction'], ARRAY['English'], 'UA', 6.5, '2013-06-12', 'now_showing'::public.movie_status, 49521),
  ('WALL·E', 'WALL·E is the last robot left on an Earth that has been overrun with garbage and all humans have fled to outer space. For 700 years he has continued to try and clean up the mess, but has developed some rather interesting human-like qualities. When a ship arrives with a sleek new type of robot, WALL·E thinks he''s finally found a friend and stows away on the ship when it leaves.', 'https://image.tmdb.org/t/p/w500/9cJETuLMc6R0bTWRA5i7ctY9bxk.jpg', 98, ARRAY['Animation','Family'], ARRAY['English'], 'UA', 7.8, '2008-06-22', 'now_showing'::public.movie_status, 10681),
  ('The Hangover', 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can''t seem to locate their best friend, Doug – who''s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.', 'https://image.tmdb.org/t/p/w500/uluhlXubGu1VxU63X9VHCLWDAYP.jpg', 100, ARRAY['Comedy'], ARRAY['English'], 'UA', 7.2, '2009-06-05', 'now_showing'::public.movie_status, 18785),
  ('Logan', 'In the near future, a weary Logan cares for an ailing Professor X in a hideout on the Mexican border. But Logan''s attempts to hide from the world and his legacy are upended when a young mutant arrives, pursued by dark forces.', 'https://image.tmdb.org/t/p/w500/gGBu0hKw9BGddG8RkRAMX7B6NDB.jpg', 137, ARRAY['Action','Drama','Science Fiction'], ARRAY['English','Español'], 'UA', 7.6, '2017-02-28', 'now_showing'::public.movie_status, 263115);
